-- iDepot Phase 1 SYNTHETIC legacy fixture (generated by scripts/make-fixture.mjs)
-- Schema is a reduced, faithful verbatim layout; every column is TEXT in legacy_raw.
SET NAMES utf8mb4;

DROP TABLE IF EXISTS opening_stock_count;
DROP TABLE IF EXISTS suppliers;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS units_items;
DROP TABLE IF EXISTS units;
DROP TABLE IF EXISTS item_category;
DROP TABLE IF EXISTS item_main_category;
DROP TABLE IF EXISTS payment;
DROP TABLE IF EXISTS invoice;
DROP TABLE IF EXISTS item;
DROP TABLE IF EXISTS store;

CREATE TABLE store (
  id INT PRIMARY KEY,
  name VARCHAR(120),
  status VARCHAR(30)
);

CREATE TABLE item (
  id INT PRIMARY KEY,
  item_code VARCHAR(40),
  name VARCHAR(200),
  quantity DOUBLE,
  status VARCHAR(30),
  created_date DATETIME,
  store_id INT,
  category_id INT,
  supplier_id INT,
  selling_price DOUBLE,
  purchase_price DOUBLE,
  unit_quantity DOUBLE,
  barcode VARCHAR(64)
);

CREATE TABLE item_main_category (
  category_id INT PRIMARY KEY,
  category_name VARCHAR(120)
);

CREATE TABLE item_category (
  category_id INT PRIMARY KEY,
  main_id INT,
  category_name VARCHAR(120)
);

CREATE TABLE units (
  unit_id INT PRIMARY KEY,
  unit_name VARCHAR(60)
);

CREATE TABLE units_items (
  id INT PRIMARY KEY,
  unit_id INT,
  item_id INT,
  unit_total DOUBLE,
  unit_price DOUBLE
);

CREATE TABLE customers (
  customer_id INT PRIMARY KEY,
  customer_name VARCHAR(200),
  contact_person VARCHAR(200),
  mobile VARCHAR(40),
  phone VARCHAR(40),
  email VARCHAR(200),
  customer_active VARCHAR(20),
  guest VARCHAR(5),
  address VARCHAR(300),
  created_date DATETIME
);

CREATE TABLE suppliers (
  supplier_id INT PRIMARY KEY,
  supplier_name VARCHAR(200),
  contact_person VARCHAR(200),
  mobile VARCHAR(40),
  phone VARCHAR(40),
  email VARCHAR(200),
  address VARCHAR(300),
  created_date DATETIME,
  opening_balance DOUBLE DEFAULT 0,
  balance_due DOUBLE DEFAULT 0,
  opening_accounts_payable_id INT
);

-- Synthetic pre-cutover physical count sheet (count-first authority, strategy §4).
CREATE TABLE opening_stock_count (
  id INT PRIMARY KEY,
  item_id INT,
  store_id INT,
  counted_quantity DOUBLE,
  counted_by VARCHAR(120),
  counted_date DATETIME
);

CREATE TABLE invoice (
  id INT PRIMARY KEY,
  invoice_code VARCHAR(40),
  so_code VARCHAR(40),
  customer_id INT,
  amount DOUBLE,
  amount_paid DOUBLE,
  amount_due DOUBLE,
  status VARCHAR(30),
  created_date DATETIME,
  store_id INT,
  date_timestamp DATETIME,
  track_code VARCHAR(40),
  opening_entry INT
);

CREATE TABLE payment (
  id INT PRIMARY KEY,
  receipt_code VARCHAR(40),
  invoice_id INT,
  amount DOUBLE,
  pay_method VARCHAR(30),
  created_date DATETIME,
  store_id INT,
  payment_type VARCHAR(30),
  category VARCHAR(30),
  customer_id INT,
  invoice_code VARCHAR(40),
  so_code VARCHAR(40),
  method_account VARCHAR(60),
  bank_name VARCHAR(120),
  branch VARCHAR(120),
  cheque_number VARCHAR(80),
  momo_phone VARCHAR(30),
  momo_transaction_id VARCHAR(80),
  momo_type VARCHAR(20),
  track_code VARCHAR(40),
  cash_sales_in_payables DOUBLE,
  due DOUBLE
);

