  amount_paid DOUBLE,
  amount_due DOUBLE,
  payment_method TEXT,
  payment_details TEXT,
  account_id INT,
  status TEXT,
  track_code VARCHAR(50),
  p_prev_paid DOUBLE,
  prev_paid DOUBLE,
  date_timestamp LONGTEXT
);
